fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since both arrays have the same length, we can safely iterate in parallel.
    // For each pair of elements, compare if a[i] >= b[i] and collect the boolean results.
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x >= y)
        .collect()
}